["Her Memories: Old Bean"]={description="Rusty Anchor Pub owner Thierride bids you deliver his latest bean cuisine to old friend and Southern San d'Oria resident Amaura. In return for this favor, Thierride promises you his full cooperation.",fame="Wings of the Goddess",id=65,previous={"Her Memories: Homecoming Queen"},reward="[Key Item] Tiny memory fragment",start_npc="Thierride",start_pos="G-7",start_zone="Batallia Downs (S)"},
