["Manifest Destiny"]={description="Having successfully turned back the Yagudo offensive, Lehko Habhoka and the Mithran mercenaries strike for Castle Oztroja to finish off their foe. The final conflict is nigh--report to the mercenary camp in the Meriphataud Mountains without delay!",fame="Wings of the Goddess",id=62,next={"At Journey's End"},previous={"Howl from the Heavens"},requirements={{count=3,id=2567,name="Dorter Key"}},reward="Hi-Reraiser",start_npc="Dhea Prandoleh",start_zone="Windurst Waters (S)"},
["Message on the Wind"]={description="Romualdo believes he has heard the voice of his deceased father in Grauberg. He'd like to head there again to find out for sure, but is unable to leave his post...",fame="Crystal War",id=1,repeatable="No",reward="Smart Grenade",start_npc="Romualdo",start_zone="Batallia Downs (S)",title="Windtalker"},
["No Rest for the Weary"]={description="Mission Orders: No sooner has one threat been quelled than another emerges. You have been granted a brief respite, but cannot help but feel concern at the state of the Voidwatch effort in the Crystal War era...",fame="Wings of the Goddess",id=88,next={"A World in Flux"},previous={"A New Menace"},reward="White stratum abyssite VI, Starlight Voidwatcher's emblem",start_npc="Voidwatch Officer"},
