["Redeeming Rocks"]={description="It seems young Kocco is always upsetting her mother with her mischieveous pranks...",id=4,reward="Kocco's Earring",start_npc="Kocco Ehllek",start_pos="H-8",start_zone="Windurst Waters"},
["Requiem for the Departed"]={description="Heptachiond is running low on the incense he lights in prayer as an offering to the departed. Apparently, the incense is made by a friend who is now at Fort Karugo-Narugo.",fame="Crystal War",id=23,reward="Recall-Meriph (Scroll)",start_npc="Heptachiond",start_pos="H-8",start_zone="The Eldieme Necropolis"},
