["Seeing Blood-red"]={description="Ulbrecht's maniacal machinations have been made clear, and only one person holds the key to tracking him down. Find Professor Schultz!",fame="Crystal War",id=34,next={"Survival of the Wisest"},previous={"Downward Helix"},reward="Scholar's M.board",start_npc="Erlene",start_zone="Batallia Downs (S)",title="Summa Cum Laude"},
["Seeing Spots"]={description="To assist in the war effort, or so he claims, Wyatt requires a number of ladybug wings to turn out some new armor.  Gather some and bring them back to him for a reward.",id=10,next={"Atelloune's Lament"},repeatable="Yes",reward="3000gil",start_npc="Wyatt",start_pos="L-6",start_zone="Southern San d'Oria",title="Lady Killer"},
["Sins of the Mothers"]={description="A state of emergency has been declared as the Shadow Lord's army marches inexorably toward the Federation. In the midst of the turmoil, Lehko Habhoka has summoned you to Heavens Tower with a task of particular import...",fame="Wings of the Goddess",id=53,next={"Howl from the Heavens"},previous={"The Forbidden Path"},reward="Kitty Rod",start_npc="Lehko Habhoka",start_zone="Windurst Waters (S)"},
["Snake on the Plains"]={description="Take a jar of Zonpa-Zippa's All-Purpose Putty to the stone towers in West Sarutabaruta (S)",id=8,next={"The Tigress Stirs"},reward="Bronze Ribbon of Service §\nSprinter's Shoes",start_npc="Miah Riyuh",start_pos="H-9",start_zone="Windurst Waters",title="Cobra Unit Mercenary"},
["Son and Father"]={description="A child stands crying by San d'Oria Eastgate. Find his father for him.",fame="Wings of the Goddess",id=57,previous={"Father and Son"},reward="Trainee's Specs.",start_npc="Exoroche",start_pos="K-9",start_zone="Southern San d'Oria"},
["Songbirds in a Snowstorm"]={description="An immense beastman force seeks to strike at the sparsely manned rearguard of the northbound Allied expedition. You have been requested to join the Carmine Swallows on their mission to intercept the encroaching enemy host at Beaucedine.",fame="Wings of the Goddess",id=51,next={"Blood of Heroes"},previous={"Bonds That Never Die"},requirements={{count=1,name="Flint Stone\nAny fishing rod"}},reward="Icarus Wing",start_npc="Rholont",start_zone="Southern San d'Oria (S)"},
["Steamed Rams"]={description="Recent sightings of an unidentified flying objects have the Royal Knights perplexed. Venture out into East Ronfaure (S)",id=9,next={"Gifts of the Griffon"},requirements={{count=1,id=921,ki=true,name="Red recommendation letter"}},reward="Bronze Ribbon of Service §\nSprinter's Shoes",start_npc="Mainchelite",start_pos="I-9",start_zone="Southern San d'Oria",title="Knight of The Iron Ram"},
["Storm on the Horizon"]={description="Senator Karst has left unescorted for a meeting with Chairman Pale Eagle. You are to accompany Mythril Musketeer Volker to the rendezvous point and bear witness to the exchange between the two leaders.",fame="Wings of the Goddess",id=35,next={"Fire in the Hole"},previous={"Burden of Suspicion"},reward="Icarus Wing",start_npc="Klara",start_pos="H-6",start_zone="Bastok Markets"},
["Succor to the Sidhe"]={description="To save their ancestral home from a fate of destruction, the fey folk would entreat your aid.",fame="Wings of the Goddess",id=55,repeatable="Yes",requirements={{count=1,name="Varies"}},reward="Varies",start_npc="Callisto",start_zone="Grauberg (S)"},
["The Dawn Also Rises"]={description="Challenging Cait Sith again requires another visit to either Ronfaure, Jugner Forest, or Beaucedine Glacier in the Shadowreign Era to gather a breath of dawn.",fame="Wings of the Goddess",id=74,previous={"Champion of the Dawn"},repeatable="Yes",requirements={{count=1,name="See walkthrough for details."}},reward="Choice of:\nPact with Cait Sith\n10,000 Gil",start_npc="Walk of Echoes (S)",title="Light of Dawn"},
["The Dawn of Delectability"]={description="The outbreak of war has done away with any semblance of motivation aspiring chef Ranpi-Monpi may have had. If only he could experience the unique and extraordinarily new delectable dish that he dreams of...",id=5,repeatable="No",requirements={{count=1,id=5473,name="Bastore Sweeper"},{count=1,id=5661,name="Walnut"},{count=1,id=5662,name="Dragon Fruit"},{count=1,id=5660,name="Pepperoni"}},reward="Trainee Knife",start_npc="Ranpi-Monpi",start_pos="E-9",start_zone="Windurst Waters",title="None"},
["The Fighting Fourth"]={description="Deliver rations to the Eduard Watchtower in North Gustaberg (S)",id=7,next={"Better Part of Valor"},reward="Bronze Ribbon of Service §\nSprinter's Shoes",start_npc="Adelbrecht",start_pos="E-9",start_zone="Bastok Markets",title="Fourth Division Soldier"},
["The Flipside of Things"]={description="Rarcasmeult has mistakenly placed a firepower case in the Firesand Storeroom. Retrive it and bring it back to him.",id=11,reward="Map of Vunkerl Inlet (Only if you do not already own it)\n2,000 Experience Points\n2,000 Gil",start_npc="Rarcasmeult",start_pos="J-6",start_zone="Garlaige Citadel"},
["The Forbidden Path"]={description="In his secret laboratory deep beneath Windurst, the genius Karaha-Baruha pores over ancient tomes, that he might once again summon the Great Beast in his nation's time of need. Deliver what he seeks to Velda-Galda by the gate to Windurst Walls!",fame="Wings of the Goddess",id=47,next={"Sins of the Mothers"},previous={"The Long March North"},requirements={{count=1,name="[Key Item]Irradiant strand\n[Key Item]Refulgent strand\n[Key Item]Scintillant strand"}},reward="Stat potion depending on job",start_npc="Lehko Habhoka",start_zone="Windurst Waters (S)",title="Karaha-Baurha's Research Assistant"},
["The Fumbling Friar"]={description="Fondactiont wants you to find and bring back an important package that he \"dropped\" into the river in Grauberg.",fame="Crystal War",id=22,reward="Recall-Pashh (Scroll)",start_npc="Fondactiont",start_pos="I-6",start_zone="Garlaige Citadel"},
["The Long March North"]={description="Battered but not beaten, the Windurstian army steels itself for a grueling march north. The first leg of the journey takes you to San d'Oria, where you and your Cobra companions will learn what trouble lies brewing on the Valdeaunian front.",fame="Wings of the Goddess",id=46,next={"The Forbidden Path"},previous={"A Feast for Gnats"},reward="Stellar Earring",start_npc="Robel-Akbel",start_zone="Windurst Waters (S)"},
["The Lost Book"]={description="A book that Yoran-Oran borrowed from the Library of Magic was supposedly stolen and taken to Giddeus by the Yagudo.",fame="Crystal War",id=26,requirements={{count=1,id=749,name="Mythril Beastcoin"},{count=1,id=2550,name="Vellum"},{count=1,id=972,ki=true,name="[Key Item] Lynx pelt"}},reward="Retrace (Scroll)",start_npc="Yoran-Oran",start_pos="J-9",start_zone="Windurst Waters"},
["The Price of Valor"]={description="Bloodwing Horde military tactician, Zogbog, has made bold claims that he holds the key to nullifying Tavnazia's impenetrable defensive walls. Help the Swiftwing Griffins in their risk-ridden mission to uncover the nature of his latest plot.",fame="Wings of the Goddess",id=44,next={"Bonds That Never Die"},previous={"In a Haze of Glory"},requirements={{count=1,name="Multiple Hatchets, for logging."}},reward="Peiste Skin",start_npc="Rahal",start_zone="Jugner Forest (S)"},
["The Swarm"]={description="A vermin infestation of unprecedented scale has broken out within the mines, severely disrupting mining operations and causing considerable financial loss to the industry. The Silvermines Pest Control Committee is urgently recruiting dauntless individuals to aid in their extermination. Items found within the premises can be utilized at your discretion.",fame="Wings of the Goddess",id=31,repeatable="Yes",requirements={{count=1,id=5741,name="Pest Repellent"}},reward="Swarminator Title",start_npc="Rolanberry Fields Fortilace",start_pos="D-9",title="Swarminator"},
["The Tigress Stirs"]={description="Volunteer mercenaries have arrived from Olzhirya just as Ajido-Marujido delivers news of a possible attack by an unseen breed of Yagudo.  Bring Ajido the starfruit he buried somewhere in West Sarutabaruta (S)",id=17,next={"The Tigress Strikes"},previous={"The Fighting Fourth","Snake on the Plains","Steamed Rams"},repeatable="No",reward="Hi-Elixir",start_npc="Dhea Prandoleh",start_pos="H-10",start_zone="Windurst Waters",title="None."},
["The Tigress Strikes"]={description="The Mithra Mercenaries have set out towards Fort Karugo-Narugo to hunt down the Yagudo.  You find yourself headed to the same destination in search of the impetuous young Ajido-Marujido.",id=18,next={"Knot Quite There"},previous={"The Tigress Stirs"},repeatable="No",reward="Star Globe",start_npc="Dhea Prandoleh",start_pos="H-10",start_zone="Windurst Waters",title="Ajido-Marujido's Minder"},
["The Truth Is Out There"]={description="Mission Orders: The existence of another planar rift has been confirmed in the Walk of Echoes. Could this one hold the answers needed to quell the Voidwalker menace once and for all? Be ever vigilant, soldiers of the Voidwatch!",fame="Wings of the Goddess",id=85,next={"Re-Drafted by the Duchy"},previous={"A Cait Calls"},start_npc="Voidwatch Officer"},
["The Truth Lies Hid"]={description="Klara Bester, erstwhile captain of the Mythril Musketeers turned fugitive, has ensconced herself deep in the heart of Castle Zvahl. You must infiltrate the enemy stronghold with your comrades and uncover the truth behind your ex-commander's treachery.",fame="Wings of the Goddess",id=58,next={"Bonds of Mythril"},previous={"What Price Loyalty"},requirements={{count=1,id=4145,name="Elixir"}},reward="Sanctus Rosary",start_npc="Gentle Tiger",start_pos="H-6",start_zone="Bastok Markets"},
["The Weekly Adventurer"]={description="Battlefield journalist Naiko-Paneiko has received intriguing leads concerning the appearance of a monster in the Rolanberry Fields.  Go nab the scoop!",id=2,repeatable="No",reward="Map of Fort Karugo-Narugo (If you do not already own it)\n2,000 Experience Points\n2,000 Gil",start_npc="Naiko-Paneiko",start_pos="L-8",start_zone="Crawlers' Nest",title="None"},
["The Young and the Threadless"]={description="Unable to keep up with the overwhelming demand for her custom charm bracelets, the Windurstian clothcrafter Ponono has entrusted you with procuring a fresh supply of enchanted thread.",fame="Wings of the Goddess",id=56,reward="Trainee Scissors",start_npc="Ponono",start_pos="K-11",start_zone="Windurst Waters"},
["Third Tour of Duchy"]={description="Mission Orders: The Duchy has requested your presence yet again. Wherever have the Voidwalkers struck this time? In any event, make haste to the palace in Ru'Lude Gardens or the main gate in Sauromugue Champaign for further orders.",id=92,next={"Glimmer of Hope"},previous={"A Farewell to Felines"},start_zone="Ru'Lude Gardens - Audience Chamber"},
["VW Op. #126: Qufim Incursion"]={description="Mission Orders: The Voidwalker presence grows ever stronger at Qufim Island, Behemoth's Dominion, and Delkfutt's Tower. Lure out and eliminate hostiles to secure the area.",fame="Wings of the Goddess",id=83,next={"A Cait Calls"},previous={"Battle on a New Front"},reward="50,000 Gil"},
["What Price Loyalty"]={description="Apprehended in Beaucedine after deserting his unit, Zeid awaits punishment in a dark cell of Benedikt Watchtower. Can nothing be done to save him from his fate? At his friend Gentle Tiger's behest, you travel to North Gustaberg to offer your aid.",fame="Wings of the Goddess",id=50,next={"The Truth Lies Hid"},previous={"Beneath the Mask"},reward="Fourth Staff",start_npc="Gentle Tiger",start_pos="H-6",start_zone="Bastok Markets",title="Presidential Protector"},
["When One Man Is Not Enough"]={description="The Mithran mercenary majors are feuding over exclusive rights to Lehko Habhoka who is now presumed to be hiding out in Sarutabaruta. Find and bring back the heartthrob before things get out of hand.",fame="Wings of the Goddess",id=39,next={"A Feast for Gnats"},previous={"A Manifest Problem"},repeatable="No",requirements={{count=1,name="Blackened Siredon, Forest Carp, Greedie, or Pipira"}},reward="12 x Red Rose",start_npc="Dhea Prandoleh",start_pos="H-10",start_zone="Windurst Waters"},
["Wrath of the Griffon"]={description="Squire Altennia has been captured by Orcs, and is being held at their encampment in southern Jugner Forest. Rescue her before it's too late!",fame="Crystal War",id=25,next={"Perils of the Griffon"},previous={"Boy and the Beast"},reward="[Key Item]Military scrip",start_npc="Rholont",start_pos="E-7",start_zone="Southern San d'Oria",title="Fine Young Griffon"},
}
